const g=document.getElementById('sg');const S=[];for(let i=0;i<39;i++){const d=document.createElement('div');d.className='seat '+(i<19?'y':'n');g.appendChild(d);S.push(d);}
const ez=x=>x<=0?0:x>=1?1:1-Math.pow(1-x,3);const ny=document.getElementById('ny'),nn=document.getElementById('nn'),nt=document.getElementById('snt');
__tick.push(t=>{let cy=0,cn=0;S.forEach((d,i)=>{const t0=0.35+i*0.045;const u=ez((t-t0)/0.3);d.style.opacity=u.toFixed(3);d.style.transform='scale('+(0.3+0.7*u).toFixed(3)+')';if(u>0.5){if(i<19)cy++;else cn++;}});ny.textContent=cy;nn.textContent=cn;const v=ez((t-(__B[1]||2.4))/0.4);nt.style.opacity=v.toFixed(3);nt.style.transform='translateY('+(20*(1-v)).toFixed(1)+'px)';});
